namespace cookies;

internal static class NetscapeCookieFileWriter
{
    internal const string Header =
        "# Netscape HTTP Cookie File\n" +
        "# https://curl.se/docs/http-cookies.html\n" +
        "# This file was generated by cookies. Edit at your own risk.\n\n";

    internal static CookieStringSerializationResult WriteFile(
        StoredCookie[] cookies,
        NetscapeCookieFileOptions options,
        ICookieClock clock)
    {
        if (!NetscapeCookieFileReader.IsValidOptions(options) || clock == null)
        {
            return CreateFailure(CookieErrorCode.InvalidConfiguration);
        }

        if (cookies == null)
        {
            return CreateFailure(CookieErrorCode.SerializationFailure);
        }

        NetscapeCookieFileOptions effective =
            CookieGraphCloner.CloneNetscapeOptions(options);
        CookieClockResult clockResult = CookieClockEvaluator.Evaluate(clock);
        if (!clockResult.Success)
        {
            return CreateFailure(CookieErrorCode.InvalidConfiguration);
        }

        global::System.Collections.Generic.List<StoredCookie> included = [];
        global::System.Collections.Generic.Dictionary<string, bool> projectedIdentities =
            new global::System.Collections.Generic.Dictionary<string, bool>();
        int index = 0;
        while (index < cookies.Length)
        {
            StoredCookie cookie = cookies[index];
            if (cookie == null || cookie.Persistent != cookie.HasExpires)
            {
                return CreateFailure(CookieErrorCode.SerializationFailure);
            }

            bool include = cookie.HasExpires ?
                effective.IncludeExpiredCookies || cookie.Expires > clockResult.Value :
                effective.IncludeSessionCookies;
            if (include)
            {
                CookieErrorCode validation = ValidateCookie(cookie, effective);
                if (validation != CookieErrorCode.None)
                {
                    return CreateFailure(validation);
                }

                if (cookie.HasPartitionKey && effective.RejectPartitionedCookies)
                {
                    return CreateFailure(CookieErrorCode.LossyImport);
                }

                string projectedIdentity = CreateProjectedIdentity(cookie);
                if (projectedIdentities.ContainsKey(projectedIdentity))
                {
                    bool priorPartitioned = projectedIdentities[projectedIdentity];
                    return CreateFailure(
                        priorPartitioned || cookie.HasPartitionKey ?
                            CookieErrorCode.LossyImport :
                            CookieErrorCode.DuplicateIdentity);
                }

                projectedIdentities.Add(projectedIdentity, cookie.HasPartitionKey);
                if (included.Count >= effective.Limits.MaximumCookies)
                {
                    return CreateFailure(CookieErrorCode.TotalLimitExceeded);
                }

                included.Add(CookieGraphCloner.CloneStoredCookie(cookie));
            }

            index = index + 1;
        }

        StoredCookie[] ordered = included.ToArray();
        CookieSnapshotWriter.SortSnapshotCookies(ordered);
        global::System.Text.StringBuilder output =
            new global::System.Text.StringBuilder(Header);
        index = 0;
        while (index < ordered.Length)
        {
            output.Append(FormatLine(ordered[index]));
            output.Append('\n');
            index = index + 1;
        }

        CookieStringSerializationResult result = new CookieStringSerializationResult();
        result.Success = true;
        result.ErrorCode = CookieErrorCode.None;
        result.Value = output.ToString();
        return result;
    }

    static CookieErrorCode ValidateCookie(
        StoredCookie cookie,
        NetscapeCookieFileOptions options)
    {
        if (!CookieStoreValidator.IsValidStoredCookie(cookie) ||
            cookie.SequenceNumber < 0 ||
            cookie.HasPartitionKey != (cookie.PartitionKey.Length > 0) ||
            cookie.SameSiteMode < CookieSameSiteMode.Default ||
            cookie.SameSiteMode > CookieSameSiteMode.None)
        {
            return CookieErrorCode.SerializationFailure;
        }

        if (ContainsControl(cookie.Name) || ContainsControl(cookie.Value) ||
            ContainsControl(cookie.Domain) || ContainsControl(cookie.Path))
        {
            return CookieErrorCode.HeaderInjection;
        }

        global::System.UriHostNameType hostType =
            global::System.Uri.CheckHostName(cookie.Domain);
        if (!cookie.HostOnly &&
            (hostType == global::System.UriHostNameType.IPv4 ||
                hostType == global::System.UriHostNameType.IPv6))
        {
            return CookieErrorCode.SerializationFailure;
        }

        int domainOctets = global::System.Text.Encoding.UTF8.GetByteCount(
            cookie.Domain) + (cookie.HostOnly ? 0 : 1);
        if (domainOctets > options.Limits.MaximumAttributeValueOctets ||
            global::System.Text.Encoding.UTF8.GetByteCount(cookie.Path) >
                options.Limits.MaximumAttributeValueOctets)
        {
            return CookieErrorCode.AttributeLimitExceeded;
        }

        if ((long)global::System.Text.Encoding.UTF8.GetByteCount(cookie.Name) +
                global::System.Text.Encoding.UTF8.GetByteCount(cookie.Value) >
                options.Limits.MaximumNameValueOctets)
        {
            return CookieErrorCode.NameValueLimitExceeded;
        }

        if (cookie.HasExpires)
        {
            global::System.DateTimeOffset utcExpires =
                cookie.Expires.ToUniversalTime();
            long unixSeconds = utcExpires.ToUnixTimeSeconds();
            if (unixSeconds <= 0 ||
                utcExpires.Ticks % global::System.TimeSpan.TicksPerSecond != 0)
            {
                return CookieErrorCode.SerializationFailure;
            }
        }

        string line = FormatLine(cookie);
        if (global::System.Text.Encoding.UTF8.GetByteCount(line) >
            options.Limits.MaximumInputLineOctets)
        {
            return CookieErrorCode.InputLimitExceeded;
        }

        return CookieErrorCode.None;
    }

    static string FormatLine(StoredCookie cookie)
    {
        global::System.Text.StringBuilder line =
            new global::System.Text.StringBuilder();
        if (cookie.HttpOnly)
        {
            line.Append("#HttpOnly_");
        }

        if (!cookie.HostOnly)
        {
            line.Append('.');
        }

        line.Append(cookie.Domain);
        line.Append('\t');
        line.Append(cookie.HostOnly ? "FALSE" : "TRUE");
        line.Append('\t');
        line.Append(cookie.Path);
        line.Append('\t');
        line.Append(cookie.Secure ? "TRUE" : "FALSE");
        line.Append('\t');
        if (cookie.HasExpires)
        {
            line.Append(cookie.Expires.ToUniversalTime().ToUnixTimeSeconds().ToString(
                global::System.Globalization.CultureInfo.InvariantCulture));
        }
        else
        {
            line.Append('0');
        }

        line.Append('\t');
        line.Append(cookie.Name);
        line.Append('\t');
        line.Append(cookie.Value);
        return line.ToString();
    }

    static string CreateProjectedIdentity(StoredCookie cookie)
    {
        CookieIdentity identity = new CookieIdentity();
        identity.Name = cookie.Name;
        identity.Domain = cookie.Domain;
        identity.Path = cookie.Path;
        return CookieIdentityUtility.CreateKey(identity);
    }

    static bool ContainsControl(string value)
    {
        int index = 0;
        while (index < value.Length)
        {
            if (CookieCharacterRules.IsControl(value[index]))
            {
                return true;
            }

            index = index + 1;
        }

        return false;
    }

    static CookieStringSerializationResult CreateFailure(
        CookieErrorCode errorCode)
    {
        CookieStringSerializationResult result =
            new CookieStringSerializationResult();
        CookieIssue issue = new CookieIssue();
        issue.ErrorCode = errorCode;
        issue.Severity = CookieParseSeverity.Error;
        issue.HasOffset = false;
        issue.SafeFragment = "";
        result.ErrorCode = errorCode;
        result.Issues = [issue];
        return result;
    }
}
